"""Compile pinned requirements templates while preserving Copier feature choices."""

import argparse
import itertools
import subprocess
import tempfile
from collections import defaultdict
from pathlib import Path

from jinja2 import Environment, StrictUndefined
from packaging.requirements import Requirement
from packaging.utils import canonicalize_name

ROOT = Path(__file__).resolve().parents[2]
ROLES = ("base", "local", "production", "tests", "build")
OPTIONS = {
    "copier__use_celery": (False, True),
    "copier__use_sentry": (False, True),
    "copier__create_nextjs_frontend": (False, True),
    "copier__mail_service": ("Amazon SES", "Mailgun", "Other SMTP"),
}
ENV = Environment(undefined=StrictUndefined, keep_trailing_newline=True)


def contexts():
    return [
        dict(zip(OPTIONS, values)) for values in itertools.product(*OPTIONS.values())
    ]


def condition(selected, variants):
    """Cover a set of feature combinations with short, exact Jinja conditions."""
    candidates = []
    for values in itertools.product(
        *[(None, *choices) for choices in OPTIONS.values()]
    ):
        fields = [
            (key, value) for key, value in zip(OPTIONS, values) if value is not None
        ]
        covered = frozenset(
            i
            for i, context in enumerate(variants)
            if all(context[key] == value for key, value in fields)
        )
        if covered and covered <= selected:
            expression = " and ".join(
                (
                    key
                    if value is True
                    else f"not {key}" if value is False else f"{key} == {value!r}"
                )
                for key, value in fields
            )
            candidates.append((covered, expression))
    remaining, terms = set(selected), []
    while remaining:
        covered, expression = min(
            candidates,
            key=lambda item: (-len(item[0] & remaining), len(item[1]), item[1]),
        )
        remaining -= covered
        terms.append(f"({expression})")
    return " or ".join(terms)


def factor_locks(variants):
    if not variants:
        raise ValueError("Cannot generate a lock without feature configurations")
    memberships = defaultdict(set)
    for i, (_, lines) in enumerate(variants):
        for line in lines:
            memberships[line].add(i)
    groups = defaultdict(list)
    for line, selected in memberships.items():
        groups[frozenset(selected)].append(line)
    output = ["# Generated by .github/scripts/python_locks.py. Do not edit by hand.\n"]
    all_indices = frozenset(range(len(variants)))
    for selected, lines in sorted(
        groups.items(), key=lambda item: (-len(item[0]), sorted(item[1]))
    ):
        if selected != all_indices:
            output.append(
                "{% if "
                + condition(selected, [context for context, _ in variants])
                + " %}\n"
            )
        output.extend(line + "\n" for line in sorted(lines))
        if selected != all_indices:
            output.append("{% endif %}\n")
    return "".join(output)


def compile_lock(inputs, output, python, constraints=None, strip_extras=False):
    command = [
        "uv",
        "pip",
        "compile",
        *map(str, inputs),
        "--output-file",
        str(output),
        "--python-version",
        python,
        "--python-platform",
        "linux",
        "--no-header",
        "--no-annotate",
        "--prerelease",
        "disallow",
        "--quiet",
    ]
    if not strip_extras:
        command.append("--no-strip-extras")
    if constraints:
        command.extend(["--constraint", str(constraints)])
    subprocess.run(command, check=True)
    return {
        line.strip()
        for line in output.read_text().splitlines()
        if line.strip() and not line.startswith("#")
    }


def render_inputs(requirements, workdir, context):
    for role in ROLES:
        text = ENV.from_string((requirements / f"{role}.in").read_text()).render(
            context
        )
        # Resolve source inputs, not yesterday's compiled base dependencies.
        (workdir / f"{role}.in").write_text(text.replace("-r base.txt", "-r base.in"))


def update_locks(root=ROOT):
    requirements = root / "template/backend/requirements"
    python = (root / "template/.python-version").read_text().strip()
    variants = {role: [] for role in ROLES}
    compiled = {}
    with tempfile.TemporaryDirectory() as directory:
        workdir = Path(directory)
        all_inputs = set()
        for context in contexts():
            render_inputs(requirements, workdir, context)
            for role in ROLES:
                all_inputs.update(
                    line
                    for line in (workdir / f"{role}.in").read_text().splitlines()
                    if line.strip() and not line.startswith(("#", "-r "))
                )
        (workdir / "all.in").write_text("\n".join(sorted(all_inputs)) + "\n")
        constraints = workdir / "constraints.txt"
        compile_lock([workdir / "all.in"], constraints, python, strip_extras=True)
        for context in contexts():
            render_inputs(requirements, workdir, context)
            for role in ROLES:
                key = (
                    (workdir / "base.in").read_text(),
                    (workdir / f"{role}.in").read_text(),
                )
                if key not in compiled:
                    compiled[key] = compile_lock(
                        [workdir / f"{role}.in"],
                        workdir / "lock.txt",
                        python,
                        constraints,
                    )
                variants[role].append((context, compiled[key]))
    # Prepare every template before replacing any existing lock.
    factored = {role: factor_locks(variants[role]) for role in ROLES}
    for role in ROLES:
        (requirements / f"{role}.txt").write_text(factored[role])


def pinned_versions(lines):
    versions = {}
    for line in lines:
        if not line.strip() or line.startswith("#"):
            continue
        requirement = Requirement(line)
        specifiers = list(requirement.specifier)
        if (
            len(specifiers) != 1
            or specifiers[0].operator != "=="
            or "*" in specifiers[0].version
        ):
            raise ValueError(f"Unpinned requirement: {line}")
        name = canonicalize_name(requirement.name)
        version = specifiers[0].version
        if name in versions and versions[name] != version:
            raise ValueError(f"Conflicting pins for {name}")
        versions[name] = version
    return versions


def requirement_extras(lines):
    extras = defaultdict(set)
    for line in lines:
        if not line.strip() or line.startswith("#"):
            continue
        requirement = Requirement(line)
        extras[canonicalize_name(requirement.name)].update(
            canonicalize_name(extra) for extra in requirement.extras
        )
    return dict(extras)


def check_locks(root=ROOT):
    requirements = root / "template/backend/requirements"
    python = (root / "template/.python-version").read_text().strip()
    variants = contexts()
    rendered = {}
    all_lines = set()
    for i, context in enumerate(variants):
        for role in ROLES:
            text = ENV.from_string((requirements / f"{role}.txt").read_text()).render(
                context
            )
            lines = frozenset(text.splitlines())
            rendered[i, role] = lines
            all_lines.update(lines)
    # Shared packages must use one version across roles and feature contexts.
    shared_versions = pinned_versions(all_lines)
    checked = set()
    with tempfile.TemporaryDirectory() as directory:
        workdir = Path(directory)
        constraints = workdir / "constraints.txt"
        constraints.write_text(
            "\n".join(
                f"{name}=={version}"
                for name, version in sorted(shared_versions.items())
            )
            + "\n"
        )
        for i, context in enumerate(variants):
            render_inputs(requirements, workdir, context)
            for role in ROLES:
                locked = rendered[i, role]
                expected = pinned_versions(locked)
                key = (
                    role,
                    (workdir / "base.in").read_text(),
                    (workdir / f"{role}.in").read_text(),
                    locked,
                )
                if key in checked:
                    continue
                checked.add(key)
                # Each role must include its own complete transitive closure.
                resolved = compile_lock(
                    [workdir / f"{role}.in"],
                    workdir / "checked.txt",
                    python,
                    constraints,
                )
                if pinned_versions(resolved) != expected or requirement_extras(
                    resolved
                ) != requirement_extras(locked):
                    raise ValueError(
                        f"Incomplete or stale Python locks for {role} in {context}"
                    )
    print(f"Validated Python locks for all {len(variants)} feature configurations")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="Validate committed locks without updating them",
    )
    args = parser.parse_args()
    check_locks() if args.check else update_locks()
